let sessionApiKey='';
async function requestJson(path,input,key=sessionApiKey){const headers={'content-type':'application/json'};if(key&&['/api/internal-search','/api/advice','/api/search','/api/liner/balance','/api/report/review'].includes(path))headers['x-packtrail-liner-key']=key;const response=await fetch(path,{method:'POST',headers,body:JSON.stringify(input)});const data=await response.json();if(!response.ok)throw Error(data.error||'요청에 실패했습니다.');return data}
const linerDialog=$('liner-dialog');linerDialog.addEventListener('close',()=>$('liner-key').value='');function showLinerBalance(data){$('liner-connection').textContent=data.source==='session'?'현재 탭의 API 키 사용 중':'서버에 설정된 API 키 사용 중';$('liner-balance').textContent='남은 크레딧: '+Number(data.balance_usd).toLocaleString('ko-KR',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:6});$('liner-message').textContent='조회 시각: '+new Date().toLocaleString('ko-KR')}async function refreshLinerBalance(key=sessionApiKey){$('liner-message').textContent='잔액을 확인하고 있습니다…';try{const data=await requestJson('/api/liner/balance',{},key);showLinerBalance(data);return true}catch(err){$('liner-connection').textContent='연결을 확인할 수 없습니다.';$('liner-balance').textContent='잔액을 불러오지 못했습니다.';$('liner-message').textContent=err.message;return false}}$('liner-open').onclick=()=>{linerDialog.showModal();refreshLinerBalance()};$('liner-close').onclick=()=>{linerDialog.close();$('liner-key').value=''};$('liner-refresh').onclick=()=>refreshLinerBalance();$('liner-apply').onclick=async()=>{const key=$('liner-key').value.trim();if(!key){$('liner-message').textContent='API 키를 입력해 주세요.';return}if(await refreshLinerBalance(key)){sessionApiKey=key;$('liner-key').value='';$('liner-message').textContent='현재 탭에 API 키를 적용했습니다. 이 키로 검색합니다.'}};$('liner-reset').onclick=async()=>{sessionApiKey='';$('liner-key').value='';await refreshLinerBalance()};
async function runExternal(){if(!latestSearch)return;const snap=latestSearch;const btn=$('external-search');btn.disabled=true;$('submit').disabled=true;$('status').className='';$('status').textContent='라이너 AI가 추가 검색 중입니다. 시간이 걸릴 수 있습니다.';try{const data=await requestJson('/api/'+snap.mode,snap.input);if(latestSearch!==snap)return;$('external-section').hidden=false;if(snap.mode==='advice'){showAnswer($('external-answer'),data.answer);showSources($('external-sources'),Array.isArray(data.references)?data.references:[])}else{showSources($('external-answer'),Array.isArray(data.references)?data.references:[]);$('external-sources').replaceChildren()}$('status').textContent=data.saved?.error?'라이너 검색은 완료됐지만 출처를 검토함에 저장하지 못했습니다.':'라이너 추가 검색이 완료됐습니다. 출처 '+(data.saved?.count||0)+'건을 검토함에 저장했습니다.'}catch(err){$('status').className='error';$('status').textContent=err.message||'라이너 연결에 실패했습니다.'}finally{btn.disabled=false;$('submit').disabled=false}}
