function readWorkProfile(){return {kind:$('work-kind').value,form:$('work-form').value,material:$('work-material').value,layer:$('work-layer').value,contact:$('work-contact').value,food:$('work-food').value,temperature:$('work-temperature').value,duration:$('work-duration').value.trim().slice(0,100),single:$('work-single').value,role:$('work-role').value}}
function workProfileSummary(p,market,hasFile){const fcm=['fcm','report'].includes(p.kind),epr=p.kind==='epr';const known=[['포장 형태',p.form],['주요 재질',p.material],['코팅·보조 재질',p.layer]];if(fcm)known.push(['식품 접촉',p.contact],['식품 종류',p.food],['사용 온도',p.temperature],['접촉 시간',p.duration]);if(epr)known.push(['포장 사용 방식',p.single],['사업자 역할',p.role]);const gaps=[];if(!p.form||p.form==='기타')gaps.push('포장 형태');if(!p.material||p.material==='기타')gaps.push('주요 재질 또는 구성');if(fcm){if(!p.layer)gaps.push('코팅·보조 재질 유무');if(!p.contact)gaps.push('식품 접촉 여부');if(!p.food)gaps.push('접촉 식품 종류');if(!p.temperature)gaps.push('사용 온도');if(!p.duration)gaps.push('접촉 시간 또는 보관 기간')}if(epr){if(!p.single)gaps.push('일회용 여부');if(!p.role||p.role==='기타')gaps.push('사업자 역할');if(market!=='California, United States')gaps.push('SB 54의 검색지역(캘리포니아)')}if(p.kind==='report'&&!hasFile)gaps.push('시험성적서 첨부');return {known:known.filter(x=>x[1]),gaps}}
function profileUsecase(p,extra){const fcm=['fcm','report'].includes(p.kind),epr=p.kind==='epr';const items=[];if(p.form)items.push('포장 형태: '+p.form);if(p.material)items.push('재질: '+p.material);if(p.layer&&p.layer!=='없음'&&p.layer!=='기타')items.push('코팅 또는 보조 재질: '+p.layer);if(fcm){if(p.contact==='직접 접촉')items.push('식품 직접 접촉');else if(p.contact)items.push('직접 접촉하지 않음');if(p.food)items.push('식품 종류: '+p.food);if(p.temperature)items.push('사용 온도: '+p.temperature);if(p.duration)items.push('접촉 시간: '+p.duration)}if(epr){items.push('캘리포니아 SB 54 생산자책임');if(p.single)items.push('사용 방식: '+p.single);if(p.role)items.push('사업자 역할: '+p.role)}if(extra)items.push('추가 조건: '+extra);return items.join(' · ').slice(0,1000)||'사용자가 별도로 명시하지 않은 경우 알 수 없음'}
for(const id of [...WORK_IDS,'query','market','topic','mode','usecase','real-report','report-product-scope','report-placement-date','report-sample-match','report-method-confirmed','report-food-contact','report-pfas-method','report-ocr-confirmed'])$(id).addEventListener('input',()=>{if(!$('result').classList.contains('hidden')){$('result').classList.add('hidden');$('status').textContent='입력 조건이 변경됐습니다. 다시 검색해 주세요.'}});
