 const hold=reason=>({...base,status:'hold',reason});
 if(body.market!==rule.market)return hold('선택한 지역과 기준의 적용 지역이 다릅니다.');
 if(body.product_scope!==rule.product_scope)return hold('시험한 대상이 포장재 또는 포장재 구성요소인지 확인되지 않았습니다.');
 if(targetedPfas&&body.food_contact!==true)return hold('해당 포장재의 식품 접촉 용도가 확인되지 않았습니다.');
