 let refs;try{const local=await internalSearch(env,body);refs=(local.results||[]).slice(0,8).map((r,i)=>({index:i+1,title:r.title,url:r.url,description:r.description||'',note:r.note||''}))}catch{return json({error:'내부 규제 자료를 불러오지 못했습니다.'},503)}
